const NS='http://www.w3.org/2000/svg';
export const colours=['#4700a3','#007e79','#d4551d','#2676c5','#af3474','#65851d','#7043d0','#b58308','#137eaa','#8b5054','#586778'];
const number=v=>Number(v).toLocaleString('en-GB',{maximumFractionDigits:2});
function el(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;return n;}
export function empty(root,text){root.replaceChildren();const p=document.createElement('p');p.className='chart-empty';p.textContent=text;root.append(p);}
export function plot(root,labels,series,{type='bar',height=300,description='Release counts',integer=false}={}){
 root.replaceChildren();if(!labels.length||!series.length){empty(root,'No releases match these filters.');return;}
 const w=1000,h=height,l=60,r=20,t=20,b=65,iw=w-l-r,ih=h-t-b;let max=0;
 for(let i=0;i<labels.length;i++)max=Math.max(max,type==='stacked'?series.reduce((s,a)=>s+(a.values[i]||0),0):Math.max(...series.map(a=>a.values[i]||0)));
 const raw=(max||1)/4,scale=10**Math.floor(Math.log10(raw)),step0=[1,2,5,10].find(n=>n*scale>=raw)*scale,niceStep=integer?Math.max(1,Math.ceil(step0)):step0;max=niceStep*4;const svg=el('svg',{viewBox:`0 0 ${w} ${h}`,role:'img','aria-label':description});svg.append(el('title',{},description));
 for(let i=0;i<=4;i++){const v=max*i/4,y=t+ih-ih*i/4;svg.append(el('line',{x1:l,x2:w-r,y1:y,y2:y,stroke:'#e8e8ee'}),el('text',{x:l-8,y:y+4,'text-anchor':'end',fill:'#656575','font-size':11},number(v)));}
 const step=iw/labels.length,x=i=>l+(i+.5)*step,y=v=>t+ih-(v||0)/max*ih;
 const every=Math.max(1,Math.ceil(labels.length/8));labels.forEach((s,i)=>{if(i%every===0||i===labels.length-1)svg.append(el('text',{x:x(i),y:h-38,'text-anchor':'end',transform:`rotate(-25 ${x(i)} ${h-38})`,fill:'#656575','font-size':10},s));});
 const stacked=Array(labels.length).fill(0);
 series.forEach((a,k)=>{const colour=colours[k%colours.length];if(type==='line'){const pts=a.values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');svg.append(el('polyline',{points:pts,fill:'none',stroke:colour,'stroke-width':2}));}
 a.values.forEach((v,i)=>{if(v===null)return;let mark;if(type==='line')mark=el('circle',{cx:x(i),cy:y(v),r:labels.length>150?2:3,fill:colour});else{const sw=step*.8,bw=type==='stacked'?sw:sw/series.length,base=type==='stacked'?stacked[i]:0;mark=el('rect',{x:l+i*step+step*.1+(type==='stacked'?0:k*bw),y:y(v+base),width:Math.max(.3,bw-.4),height:Math.max(0,ih*v/max),fill:colour,rx:1});stacked[i]+=v;}
 const label=`${labels[i]} · ${a.name}: ${number(v)}`;mark.setAttribute('aria-label',label);if(labels.length*series.length<100)mark.setAttribute('tabindex','0');mark.append(el('title',{},label));svg.append(mark);});});root.append(svg);
}
export function heatmap(root,values){root.replaceChildren();const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];const svg=el('svg',{viewBox:'0 0 1000 300',role:'img','aria-label':'Average releases by weekday and UK hour'}),max=Math.max(0,...values.flat().filter(v=>v!==null));for(let h=0;h<24;h++)svg.append(el('text',{x:112+h*36,y:22,'text-anchor':'middle','font-size':11,fill:'#656575'},String(h).padStart(2,'0')));values.forEach((row,d)=>{svg.append(el('text',{x:90,y:54+d*34,'text-anchor':'end','font-size':12,fill:'#474755'},days[d]));row.forEach((v,h)=>{const strength=v===null?0:max?v/max:0;const c=v===null?'#fff':`rgb(${Math.round(244-173*strength)},${Math.round(240-240*strength)},${Math.round(250-87*strength)})`;const rect=el('rect',{x:96+h*36,y:34+d*34,width:33,height:30,rx:3,fill:c,stroke:v===null?'#ddd':'none'});const label=days[d]+' '+String(h).padStart(2,'0')+':00 · '+(v===null?'No complete-day coverage':number(v)+' releases on average');rect.setAttribute('aria-label',label);rect.setAttribute('tabindex','0');rect.append(el('title',{},label));svg.append(rect);});});root.append(svg);}
export function rankBars(root,rows){root.replaceChildren();if(!rows.length)return empty(root,'No releases match these filters.');const max=Math.max(1,...rows.map(r=>r.count));for(const r of rows){const line=document.createElement('div');line.className='rank-row';const name=document.createElement('span');name.textContent=r.name;const track=document.createElement('div');track.className='rank-track';const fill=document.createElement('div');fill.className='rank-fill';fill.style.width=(r.count/max*100)+'%';track.append(fill);const count=document.createElement('strong');count.textContent=number(r.count);line.append(name,track,count);root.append(line);}}
export function table(root,rows){root.replaceChildren();const table=document.createElement('table'),head=document.createElement('thead'),body=document.createElement('tbody');rows.forEach((r,i)=>{const tr=document.createElement('tr');for(const v of r){const c=document.createElement(i?'td':'th');c.textContent=typeof v==='number'?number(v):String(v??'');tr.append(c);} (i?body:head).append(tr);});table.append(head,body);root.append(table);}
